import AuthenticationServices
import SwiftUI

struct WelcomeView: View {
    @ObservedObject var session: SessionStore
    @StateObject private var onboarding = OnboardingStore(); @State private var email = ""; @State private var username = ""; @State private var password = ""; @State private var mode: Mode = .welcome
    enum Mode { case welcome, email, onboarding }
    var body: some View { NavigationStack { Group { switch mode { case .welcome: welcome; case .email: emailForm; case .onboarding: onboardingForm } }.padding(24).background(PlumStyle.cream.ignoresSafeArea()).navigationTitle(mode == .welcome ? "Plum" : "") } }
    private var welcome: some View { VStack(alignment: .leading, spacing: 18) { Spacer(); Text("A food journal\nfor your city.").font(.system(size: 38, weight: .semibold, design: .serif)).foregroundStyle(.plum); Text("Log dishes, save places, and follow people whose taste you trust.").foregroundStyle(.secondary); SignInWithAppleButton(.continue) { _ in } onCompletion: { _ in mode = .onboarding }.signInWithAppleButtonStyle(.black).frame(height: 50); Button { mode = .onboarding } label: { Label("Continue with Google", systemImage: "g.circle.fill").frame(maxWidth: .infinity) }.buttonStyle(.bordered).tint(.plum).frame(height: 50); Button("Use email or username") { mode = .email }.frame(maxWidth: .infinity); Text("Sign-in providers are configured in Supabase. No passwords are stored by Plum.").font(.caption).foregroundStyle(.secondary); Spacer() } }
    private var emailForm: some View { Form { Section("Account") { TextField("Email", text: $email).textInputAutocapitalization(.never).keyboardType(.emailAddress); TextField("Username", text: $username).textInputAutocapitalization(.never); SecureField("Password", text: $password) }; Button("Continue") { Task { do { try await session.signIn(email: email, password: password); mode = .onboarding } catch { try? await session.signUp(email: email, password: password, username: username); mode = .onboarding } } }.disabled(email.isEmpty || username.isEmpty || password.count < 8) } }
    private var onboardingForm: some View { Form { Section("Your area (optional)") { TextField("City", text: $onboarding.city); TextField("Neighborhood", text: $onboarding.neighborhood) }; Section("Get started (optional)") { Toggle("Log places I already know", isOn: $onboarding.wantsToLog); Toggle("Save places I want to try", isOn: $onboarding.wantsToSave) }; Button("Finish") { onboarding.isComplete = true }; Button("Skip for now") { onboarding.isComplete = true }.foregroundStyle(.secondary) }.navigationTitle("Make Plum yours") }
}
